"use client"

import { useEffect, useState } from "react"
import { PortalShell, StateMessage } from "../../components/PortalShell"
import { api } from "../../lib/api"

type Settings = { id: string; name: string; imageUrl: string | null; contactPhone: string | null; contactEmail: string | null; address: string | null; upiId: string | null; upiAccountLast4: string | null; paymentDisplayName: string | null; qrImageUrl: string | null; cashCollectionEnabled: boolean; upiCollectionEnabled: boolean; paymentInstructions: string | null }
type Identity = { vendor: { id: string } | null }
const isValidUpiId = (value: string) => /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}@[A-Za-z][A-Za-z0-9.-]{1,63}$/.test(value.trim())

export default function VendorSettings() {
  const [vendorId, setVendorId] = useState("")
  const [settings, setSettings] = useState<Settings | null>(null)
  const [message, setMessage] = useState("")
  const [error, setError] = useState("")
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  useEffect(() => { (async () => { try { const identity = await api<Identity>("/api/v1/marketplace/me"); if (!identity.vendor) throw new Error("Vendor access is not configured"); setVendorId(identity.vendor.id); setSettings(await api<Settings>(`/api/v1/marketplace/vendors/${identity.vendor.id}/payment-settings`)) } catch (e) { setError(e instanceof Error ? e.message : "Unable to load settings") } finally { setLoading(false) } })() }, [])
  async function save() { if (!settings || saving) return; setError(""); if (settings.upiId && !isValidUpiId(settings.upiId)) { setError("Enter a valid UPI ID/VPA."); return } if (settings.upiCollectionEnabled && !isValidUpiId(settings.upiId || "")) { setError("Configure a valid UPI ID/VPA before enabling UPI collection."); return } if (settings.upiAccountLast4 && !/^\d{4}$/.test(settings.upiAccountLast4)) { setError("Enter exactly four numeric account digits."); return } setSaving(true); try { setSettings(await api<Settings>(`/api/v1/marketplace/vendors/${vendorId}/payment-settings`, { method: "PATCH", body: JSON.stringify(settings) })); setMessage("Settings saved") } catch (e) { setError(e instanceof Error ? e.message : "Unable to save settings") } finally { setSaving(false) } }
  const links = [{ label: "Dashboard", href: "/vendor/dashboard" }, { label: "Products", href: "/vendor/products" }, { label: "Orders", href: "/vendor/orders" }, { label: "Delivery partners", href: "/vendor/delivery-partners" }, { label: "Payments", href: "/vendor/payments" }, { label: "Settings", href: "/vendor/settings" }]
  return <PortalShell title="Vendor settings" subtitle="Manage your business details and direct cash/UPI collection options." links={links}>{message && <StateMessage>{message}</StateMessage>}{error && <StateMessage error>{error}<br /><button onClick={() => window.location.reload()}>Try again</button></StateMessage>}{loading ? <StateMessage>Loading vendor settings...</StateMessage> : settings && <section className="portal-panel"><div className="settings-section"><p className="market-kicker">BUSINESS PROFILE</p><h2>Business details</h2><div className="portal-form"><label>Business name<input value={settings.name} onChange={(event) => setSettings({ ...settings, name: event.target.value })} required /></label><label>Business image URL<input value={settings.imageUrl || ""} onChange={(event) => setSettings({ ...settings, imageUrl: event.target.value || null })} placeholder="https://..." /></label><label>Contact phone<input value={settings.contactPhone || ""} onChange={(event) => setSettings({ ...settings, contactPhone: event.target.value || null })} /></label><label>Contact email<input type="email" value={settings.contactEmail || ""} onChange={(event) => setSettings({ ...settings, contactEmail: event.target.value || null })} /></label><label>Business address<textarea value={settings.address || ""} onChange={(event) => setSettings({ ...settings, address: event.target.value || null })} /></label></div></div><div className="settings-section"><p className="market-kicker">COLLECTION OPTIONS</p><h2>Cash and UPI</h2><div className="portal-form"><label>UPI ID / VPA<input value={settings.upiId || ""} onChange={(event) => setSettings({ ...settings, upiId: event.target.value || null, ...(isValidUpiId(event.target.value) ? {} : { upiCollectionEnabled: false }) })} placeholder="vendor@upi" /></label><label>Associated account (last 4 digits)<input type="password" inputMode="numeric" pattern="[0-9]{4}" maxLength={4} value={settings.upiAccountLast4 || ""} onChange={(event) => setSettings({ ...settings, upiAccountLast4: event.target.value || null })} autoComplete="off" /></label>{settings.upiAccountLast4 && <p>Saved account ending: •••• {settings.upiAccountLast4}</p>}<label>UPI display/business name<input value={settings.paymentDisplayName || ""} onChange={(event) => setSettings({ ...settings, paymentDisplayName: event.target.value || null })} /></label><label>QR image URL<input value={settings.qrImageUrl || ""} onChange={(event) => setSettings({ ...settings, qrImageUrl: event.target.value || null })} placeholder="https://..." /></label><label>Payment instructions<textarea value={settings.paymentInstructions || ""} onChange={(event) => setSettings({ ...settings, paymentInstructions: event.target.value || null })} /></label><label className="check-label"><input type="checkbox" checked={settings.cashCollectionEnabled} onChange={(event) => setSettings({ ...settings, cashCollectionEnabled: event.target.checked })} /> Cash collection enabled</label><label className="check-label"><input type="checkbox" checked={settings.upiCollectionEnabled} disabled={!isValidUpiId(settings.upiId || "")} onChange={(event) => setSettings({ ...settings, upiCollectionEnabled: event.target.checked })} /> UPI collection enabled</label><button onClick={save} disabled={saving}>{saving ? "Saving settings..." : "Save settings"}</button></div></div></section>}</PortalShell>
}
